#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
zipper zipper_from_tree(tree*r){zipper z={r,r,NULL,0};return z;}static bool down(zipper*z,tree*t){if(!t)return false;z->ancestors=(tree**)realloc(z->ancestors,(z->depth+1)*sizeof(tree*));z->ancestors[z->depth++]=z->focus;z->focus=t;return true;}bool zipper_left(zipper*z){return z->focus&&down(z,z->focus->left);}bool zipper_right(zipper*z){return z->focus&&down(z,z->focus->right);}bool zipper_up(zipper*z){if(!z->depth)return false;z->focus=z->ancestors[--z->depth];return true;}int zipper_value(const zipper*z){return z->focus->value;}void zipper_set_value(zipper*z,int v){z->focus->value=v;}void zipper_set_left(zipper*z,tree*t){z->focus->left=t;}void zipper_set_right(zipper*z,tree*t){z->focus->right=t;}tree*zipper_to_tree(const zipper*z){return z->root;}void zipper_free(zipper*z){free(z->ancestors);z->ancestors=NULL;}

